action.mutation:
mutation CreateShipment($payload: [ShipmentCreatePayloadInput!]!) {
  mutation: createShipment(payload: $payload) { 
    id
    number
  }
}

mutation UpdateShipment($payload: [ShipmentUpdatePayloadInput!]!) {
  mutation: updateShipment(payload: $payload) { 
    id
    number
  }
}
